d]);v11_event($id,'smtp_accepted',['recipient'=>$to]);$ok='SMTP sunucusu e-postayı kabul etti. Teslim veya okunma garantisi değildir.';}catch(Throwable $e){if($sendStarted)sm_log($id,$to,'failed','SMTP gönderim hatası');throw $e;}}catch(Throwable $e){$err=$e->getMessage();}}
